        "a voice that sings what you type, the kind that pulls you in. type it in the roll (LYRICS on the clip): kana, or romaji like \"a i shi te ru\", one sound a note, ー holds the last one. MASC ↔ FEM = whose throat (the mouth, the cords, the air through them), DARK ↔ LIGHT = the throat dropped + covered or up + bright, NASAL = through the nose, HUMAN ↔ ROBOT = a person to a machine, METAL = it rings like its made of it, SCREAM = past clean into torn, SING ↔ SPEAK = from a held note to just talking, BREATH all the way = a whisper, TENSION = soft + breathy to pushed + ringing, STACK = more of her": "入力した言葉を歌う、引き込まれるような声。ロールで入力 (クリップの歌詞): かな、または「a i shi te ru」のようなローマ字。音符一つに一音、ー で前の音を伸ばす。男 ↔ 女 = 誰の喉か (口の形、声帯、そこを通る息)、暗 ↔ 明 = 喉を下げてこもらせるか、上げて明るくするか、鼻声 = 鼻に抜ける、人 ↔ 機械 = 人間から機械まで、金属 = 金属でできているように響く、絶叫 = きれいな声を越えて裂ける、歌 ↔ 話 = 伸ばして歌うから、ただ話すまで、息を一番上まで = ささやき、張り = 柔らかく息まじりから、押して響く声まで、重ね = 声を増やす",
