        "lid on, nothing on fire, good": "蓋よし、何も燃えてない、よし",
        "one more loop, then another, then i look up and its morning": "もう一回ループ、もう一回、顔を上げたら朝",
        "scorch the bass, not the vocal (or do, im not your mum)": "焦がすのはベース、ボーカルじゃない (やってもいいけど、ママじゃないし)",
        "velocity on the hats. sixteen identical hits is a machine, and not the fun kind": "ハットにベロシティを。同じ16発は機械、しかも楽しくない方の",
