        "a little HUMAN on the hats, none on the kick": "ハットに少し人間味、キックにはなし",
        "phrygian is the evil one. that flat second does all the work": "フリジアンは悪い子。あのフラットした2度が全部やってくれる",
        "pump it on the 1/4, its the law": "4分でポンプ、それが掟",
        "no presets. you make it or theres nothing ♡": "プリセットなんてない。自分で作るか、何もないか ♡",
        "the presets are just knobs. turn them till theyre yours ♡": "プリセットはただのつまみ。自分のものになるまで回して ♡",
        "the low end lives in the middle. pan the bass and it walks off": "低音は真ん中に住む。ベースをパンしたら出ていく",
        "if the scope looks like a sausage, you squeezed it": "スコープがソーセージに見えたら潰しすぎ",
        "sidechain everything, ask questions later": "全部サイドチェイン、質問は後で",
        "two notes and a filter is a whole song if you mean it": "本気なら二つの音とフィルターで一曲になる",
        "check it in mono. if the bass vanishes your stereo is lying to you": "モノで確認して。ベースが消えたらステレオが嘘ついてる",
        "turn the room off and see if it still works": "部屋を切っても成立するか聴いてみて",
        "bounce at 24 bit if you love it": "愛してるなら24ビットで書き出して",
        "a dotted 1/8 echo fixes most sad things": "付点8分のエコーは悲しいことをだいたい治す",
        "automate the filter over 16 bars. nobody notices, everybody feels it": "16小節かけてフィルターをオートメーション。誰も気づかない、全員感じる",
        "the sweep goes up when you cant say it": "言えない時にスウィープが上がる",
        "it sounded better at 3am": "朝3時の方がよく聞こえた",
        "if you can hear the hiss on purpose its art": "わざとヒスが聞こえるならそれはアート",
        "ctrl+e splits, ctrl+d doubles, ctrl+j glues it back. cut shit up": "ctrl+eで分割、ctrl+dで複製、ctrl+jでくっつける。切り刻め",
        "if your arse doesnt move, its the bass. not the master, the bass": "ケツが動かないならベースのせい。マスターじゃなくてベース",
        "pick the key on the top bar first, the chord book + the roll follow it": "まずトップバーでキーを選んで。コード帳とロールがついてくる",
        "PUNCH under 6 on the loudness meter = you squeezed the life out of it": "音圧メーターのPUNCHが6未満 = 命まで搾り取った",
        "a riser into the drop, cut it a beat early. the gap is the hit": "ドロップ前のライザーは1拍早く切る。その隙間が一撃",
        "reverb tails should drip, not flood": "リバーブの尾は垂れるもの、溢れるものじゃない",
