        "three chords and a sub, played like you mean it, beats ten chords played scared": "コード三つとサブを本気で弾く方が、怖がって弾く十個より強い",
        "a 1/16 ECHO on the acid line with the feedback just under howling": "アシッドラインに16分のECHO、フィードバックは吠える寸前で",
