        "the wavetable synth: three oscillators reading tables you morph through (or their harmonics, or a sound you give it, in grains or straight), FM from anything, a sub, noise, two filters, a distortion, four envelopes, four lfos + a sixteen slot matrix. hover any dial for what it does. the map on the left is the sound right now: what goes where, lit if its on": "ウェーブテーブル・シンセ: テーブルを変形させながら読む三つのオシレーター (その倍音でも、あげた音を粒でもそのままでも)、何からでも FM、サブ、ノイズ、フィルター二つ、歪み、エンベロープ四つ、LFO 四つ + 十六スロットのマトリクス。つまみに乗せると何をするか出る。左の図は今の音: 何がどこへ行くか、点いていれば使われている",
