        "the squeeze. CLEAN, GLUE (the master bus one), SLOW (smooth, optical: the longer it holds the slower it lets go), FAST (crush it, drums), VARI-MU (a valve: the harder you push the harder it holds), UPWARD (lifts the quiet bits instead). CHARACTER sets it up for a job: VOCAL (even, quick), MASTER (barely there, just holding it), PUNCH (lets the hit through, then grabs), SMASH (every button in, the room mic sound). SIDE LOW CUT stops the bass pumping it, MIX = squeeze it in parallel": "締め付け。CLEAN、GLUE (マスターバスの定番)、SLOW (なめらかな光学式: 長く押さえるほどゆっくり離す)、FAST (潰す、ドラム向け)、VARI-MU (真空管: 押すほど強く掴む)、UPWARD (逆に小さい音を持ち上げる)。CHARACTER は用途別の設定: VOCAL (均一で速い)、MASTER (ほとんど触らず支えるだけ)、PUNCH (アタックを通してから掴む)、SMASH (全ボタン押し、ルームマイクの音)。SIDE LOW CUT で低音にポンピングさせない、MIX = パラレルで締める",
