        "the resonance tamer. it listens to the whole spectrum as it plays + finds the bits standing up out of their neighbours (the whistle in a hard synth, the ring in a snare, the harsh honk in a voice) + pushes only those down, only while theyre there. DEPTH = how far, SENSE = how far up a bit has to stand before its touched, SHARP = only narrow rings or broader bumps too, LOW + HIGH = where it looks, DELTA = hear only what its taking out. it runs a frame late (the track gets lined up)": "レゾナンスを抑えるもの。鳴っている間ずっとスペクトル全体を聞いて、周りから突き出た所 (硬いシンセの笛、スネアの鳴り、声の耳障りなホンク) を見つけ、そこだけを、そこにある間だけ下げる。DEPTH = どれだけ、SENSE = どれだけ突き出たら触るか、SHARP = 細い鳴りだけか広いこぶもか、LOW と HIGH = どこを見るか、DELTA = 取り除いているものだけを聞く。1フレーム遅れて鳴る (トラックは揃えられる)",
