        "shh. listen": "しっ。聞いて",
        "the low end, fixed. SUB = a new one an octave under (the old octave pedal trick), HARMONICS = the lows bent into overtones a laptop can play so your ear fills the bottom back in. CROSSOVER = where low starts. PULL BACK = less of the original lows to make room. kicks, 808s, darkwave basses that vanish on a phone": "低音を直す。SUB = 一オクターブ下に新しい低音 (昔のオクターブペダルの技)、HARMONICS = 低音を倍音に曲げて、ノートPCでも鳴らせるように。耳が底を補ってくれる。CROSSOVER = どこから低音か。PULL BACK = 元の低音を少し引いて場所を空ける。スマホで消えるキック、808、ダークウェーブのベースに",
        "a wavefolder. FOLD pushes the wave past the top + it folds back on itself, again + again: new harmonics without going square. SINE round, TRIANGLE sharp, TWICE through two of them. OFFSET folds one side more (it gets hollow + nasty). TONE takes the fizz off after. industrial, cyberpunk, the bass that sounds like a machine chewing": "ウェーブフォルダー。FOLD で波を天井の先へ押すと、何度も何度も折り返す: 矩形にならずに新しい倍音。SINE は丸く、TRIANGLE は鋭く、TWICE は二回通す。OFFSET は片側を多く折る (中が空いて意地悪になる)。TONE は後でジリジリを取る。インダストリアル、サイバーパンク、機械が噛んでるみたいなベース",
        "distortion in three bands. the sound split at LOW SPLIT + HIGH SPLIT (it adds back up flat), each band its own DRIVE + LEVEL, one STYLE for all three: WARM, BITE, FUZZ. the trick every hardstyle lead + every industrial bass does: keep the bottom clean + solid, burn the middle, let the top hiss": "三つの帯域で歪ませる。LOW SPLIT と HIGH SPLIT で音を分ける (足すと平らに戻る)、各帯域に DRIVE と LEVEL、STYLE は三つ共通: WARM、BITE、FUZZ。ハードスタイルのリードとインダストリアルのベースが皆やる技: 底はきれいで硬く、真ん中を焼いて、上はしゃーっと",
        "CROSSOVER": "クロスオーバー",
