        "the hardstyle screech. it dives into the note, gets wrecked twice + dragged through a vowel that WOBBLEs in time. DIRT before, TEAR after, VOWEL + SWEEP for the mouth. loud": "ハードスタイルの悲鳴。上から音に飛び込んで、二回壊されて、テンポに合わせて WOBBLE する母音の中を引きずり回される。DIRT が前、TEAR が後、口は VOWEL と SWEEP。うるさい",
        "the bass guitar. picked or plucked, a bit of GRIT, the CHORUS everyone had in 1983. play it high up the neck + let the synths have the bottom, or dont": "ベースギター。ピックか指、少しの GRIT、1983年にみんなが付けてた CHORUS。ネックの高い所で弾いて底はシンセに任せる、か任せない",
